const body = $json.body ?? $json;
if (![2, 3].includes(body.schema_version)) throw new Error('unsupported telemetry schema_version');
if (typeof body.collector_id !== 'string' || !body.collector_id) throw new Error('collector_id is required');
if (typeof body.observed_at !== 'string' || !body.observed_at) throw new Error('observed_at is required');

const specs = [
  { array: 'runs', kind: 'run', required: ['event_id', 'session_id', 'profile', 'started_at', 'fingerprint'] },
  { array: 'goal_runs', kind: 'goal_run', required: ['event_id', 'session_id', 'profile', 'model', 'status', 'started_at', 'fingerprint'] },
  { array: 'hermes_session_samples', kind: 'hermes_session_sample', required: ['event_key', 'session_hash', 'profile', 'source', 'model', 'started_at', 'sampled_at', 'fingerprint'] },
  { array: 'hermes_tool_events', kind: 'hermes_tool_event', required: ['event_key', 'session_hash', 'profile', 'tool', 'occurred_at', 'fingerprint'] },
  { array: 'hermes_tool_log_events', kind: 'hermes_tool_log_event', required: ['event_key', 'session_hash', 'profile', 'tool', 'status', 'occurred_at', 'fingerprint'] },
  { array: 'orca_usage', kind: 'orca_usage', required: ['event_id', 'usage_date', 'agent', 'model', 'project_hash', 'fingerprint'] },
  { array: 'orca_thread_usage', kind: 'orca_thread_usage', required: ['event_id', 'thread_id', 'usage_date', 'agent', 'model', 'project_hash', 'fingerprint'] },
  { array: 'orca_call_events', kind: 'orca_call_event', required: ['event_key', 'agent', 'model', 'origin_namespace', 'session_id_hash', 'source_request_id_hash', 'project_key', 'fingerprint'] },
  { array: 'orca_task_manifests', kind: 'orca_task_manifest', required: ['task_id', 'attempt_id', 'revision', 'producer_id', 'project_key'] },
  { array: 'orca_task_results', kind: 'orca_task_result', required: ['event_id', 'task_id', 'attempt_id', 'result_revision', 'producer_id'] },
  { array: 'kanban_tasks', kind: 'kanban_task', required: ['event_id', 'board', 'task_id', 'status', 'fingerprint'] },
  { array: 'kanban_task_runs', kind: 'kanban_task_run', required: ['event_id', 'board', 'run_id', 'task_id', 'status', 'fingerprint'] },
  { array: 'kanban_task_events', kind: 'kanban_task_event', required: ['event_id', 'board', 'source_event_id', 'task_id', 'kind', 'fingerprint'] },
  { array: 'kanban_task_links', kind: 'kanban_task_link', required: ['event_id', 'board', 'parent_id', 'child_id', 'fingerprint'] },
];

const items = [];
for (const spec of specs) {
  const values = body[spec.array] ?? [];
  if (!Array.isArray(values)) throw new Error(`${spec.array} must be an array`);
  if (values.length > 100) throw new Error(`${spec.array} batch exceeds 100`);
  for (const item of values) {
    if (!item || typeof item !== 'object') throw new Error(`${spec.kind} must be an object`);
    for (const field of spec.required) {
      if (item[field] === undefined || item[field] === null || item[field] === '') {
        throw new Error(`${spec.kind}.${field} is required`);
      }
    }
    items.push({ json: { entity_kind: spec.kind, collector_id: body.collector_id, observed_at: body.observed_at, item } });
  }
}
if (items.length === 0) return [{ json: { entity_kind: 'noop', collector_id: body.collector_id, observed_at: body.observed_at, item: {} } }];
return items;
